SELECT 
FROM `iot_device` d



        AND d.user_id = #{userId}


        AND d.plot_id = #{plotId}


        AND p.plot_name LIKE CONCAT('%', #{plotName}, '%')


        AND d.device_code LIKE CONCAT('%', #{deviceCode}, '%')


        AND d.name LIKE CONCAT('%', #{name}, '%')


        AND d.type_id = #{typeId}


        AND d.control_status = #{controlStatus}


        AND d.online_status = #{onlineStatus}


        AND d.health_status = #{healthStatus}


ORDER BY d.id DESC

SELECT COUNT(1)
FROM `iot_device`
WHERE device_code = #{deviceCode}

    AND id != #{excludeId}
